<script lang="ts">
 import {Api,ApiFailure} from './api';
 import type {MemberProfile} from './types';
 let {api,revision,onleaderboard,onprofile,onautherror}:{api:Api;revision:unknown;onleaderboard:()=>void;onprofile:(handle:string)=>void;onautherror:(e:unknown)=>void}=$props();
 let profile=$state<MemberProfile|null>(null);let handle=$state('');let visible=$state(false);let busy=$state(false);let error=$state('');let notice=$state('');let generation=0;
 function failure(e:unknown){error=e instanceof Error?e.message:'Could not load your profile.';if(e instanceof ApiFailure&&e.code==='auth_required')onautherror(e);}
 function apply(p:MemberProfile){profile=p;handle=p.handle??'';visible=p.public_profile;}
 async function load(){const current=++generation;busy=true;error='';try{const p=await api.profile();if(current===generation)apply(p);}catch(e){if(current===generation)failure(e);}finally{if(current===generation)busy=false;}}
 $effect(()=>{void revision;void load();return()=>{generation++;};});
 async function save(){if(busy)return;busy=true;error='';notice='';try{apply(await api.saveProfile(handle.trim()||null,visible));notice=visible?'Your public profile is visible.':'Your profile is private.';}catch(e){failure(e);}finally{busy=false;}}
</script>
<section class="member-panel" aria-label="Membership and contribution points">
 <div class="member-heading"><div><span class="eyebrow">YOUR COMMUNITY IMPACT</span><h2>Every useful structure counts.</h2></div><button class="text-button" onclick={onleaderboard}>View leaderboard →</button></div>
 {#if error}<p class="member-error" role="alert">{error} {#if !profile}<button class="text-button" onclick={load}>Retry profile</button>{/if}</p>{/if}
 {#if notice}<p class="member-notice" role="status">{notice}</p>{/if}
 {#if profile}<dl class="member-metrics"><div><dt>Contribution points</dt><dd data-testid="member-points">{profile.total_points}</dd><small>{profile.approved_contributions} approved {profile.approved_contributions===1?'template':'templates'}</small></div><div><dt>My overall rank</dt><dd data-testid="overall-rank">{profile.overall_rank?'#'+profile.overall_rank:'Not ranked'}</dd><small>Visible only to you</small></div><div><dt>My public rank</dt><dd data-testid="public-rank">{profile.public_rank?'#'+profile.public_rank:'Not ranked'}</dd><small>{profile.public_profile?'Among public contributors':'Choose to join the public board'}</small></div></dl>
 <p class="points-policy">Earn {profile.points_per_approval} points for each approved template that stays public. Withdrawing it removes those points. Views, copies and sign-ups do not earn points.</p>{:else if busy}<p role="status">Loading your membership…</p>{/if}
 <form onsubmit={(e)=>{e.preventDefault();void save();}}><div class="profile-fields"><div><label for="public-handle">Public handle <span>optional</span></label><div class="handle-field"><span aria-hidden="true">@</span><input id="public-handle" bind:value={handle} autocomplete="nickname" maxlength="24" pattern="[A-Za-z0-9][A-Za-z0-9-]*[A-Za-z0-9]" placeholder="your-handle" disabled={busy||!profile} aria-describedby="handle-help"/></div><small id="handle-help">3–24 letters, numbers or hyphens. Your email stays private.</small></div><button class="secondary" disabled={busy||!profile||(visible&&!handle.trim())}>{busy?'Saving…':'Save profile'}</button></div>
 <label class="visibility-choice"><input type="checkbox" bind:checked={visible} disabled={busy||!profile}/><span>Show my handle, points and approved templates publicly.<small>Your public profile is optional. Only contributors with points appear on the leaderboard.</small></span></label>
 </form>{#if profile?.public_profile&&profile.handle}<button class="text-button public-profile-link" onclick={()=>onprofile(profile!.handle!)}>View my public profile ↗</button>{/if}
</section>
<style>
 .member-panel{border:1px solid #dce2d3;border-radius:16px;background:#f0f4e9;padding:26px;margin-bottom:26px;min-width:0}.member-heading{display:flex;justify-content:space-between;gap:16px;align-items:center}.member-heading h2{font-size:22px;margin:9px 0;letter-spacing:-.6px}.member-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:24px 0 16px}.member-metrics>div{border-left:1px solid #d6dfc9;padding-left:18px;min-width:0}.member-metrics>div:first-child{border:0;padding:0}.member-metrics dt{font-size:12px;color:#64755b}.member-metrics dd{font-size:29px;letter-spacing:-1px;margin:10px 0}.member-metrics small,.points-policy{font-size:11px;line-height:1.7;color:#718166}.points-policy{padding-bottom:20px;border-bottom:1px solid #d6dfc9}.profile-fields{display:flex;gap:16px;align-items:center;margin-top:20px}.profile-fields>div{flex:1;min-width:0}.profile-fields label{display:block;font-size:12px;margin-bottom:8px}.profile-fields label span{font-size:10px;color:#818e77;margin-left:5px}.handle-field{display:flex;gap:8px;align-items:center;border:1px solid #d1dcc4;background:#fff;border-radius:7px;padding-left:12px;max-width:380px}.handle-field input{border:0!important;background:transparent;min-width:0;width:100%;box-shadow:none!important}.profile-fields small{font-size:10px;color:#718166;display:block;margin-top:7px;line-height:1.7}.visibility-choice{display:flex;align-items:flex-start;gap:10px;margin-top:19px;font-size:12px;line-height:1.7}.visibility-choice input{width:16px;height:16px;flex:none;margin-top:3px}.visibility-choice small{display:block;color:#718166;font-size:10px}.public-profile-link{margin-top:12px}.member-error{font-size:12px;color:#a44230}.member-notice{font-size:12px;color:#42643b}@media(max-width:650px){.member-panel{padding:20px}.member-heading{align-items:flex-start;flex-direction:column;gap:5px}.member-metrics{gap:10px}.member-metrics>div{padding-left:9px}.member-metrics dd{font-size:20px}.member-metrics dt,.member-metrics small{font-size:10px}.profile-fields{align-items:stretch;flex-direction:column}.handle-field{max-width:none}}
</style>
